{
  "findings": [
    {
      "check_id": "CKV_AWS_53",
      "title": "S3 block public ACLs is not enabled",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "CRITICAL",
      "explanation": "The CloudTrail log bucket has no S3 Public Access Block configuration, so public ACLs are not explicitly prevented. This could expose sensitive audit logs if a public ACL is later applied."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 access logging is not enabled",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "HIGH",
      "explanation": "The bucket does not record S3 access requests, reducing the ability to investigate unauthorized or anomalous access to CloudTrail logs."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 Public Access Block is missing",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "The bucket has no account-independent resource-level controls blocking public policies and ACLs. An accidental policy or ACL change could therefore make the log bucket public."
    },
    {
      "check_id": "CKV2_AWS_61",
      "title": "S3 lifecycle configuration is missing",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "The bucket has no lifecycle configuration, leaving incomplete multipart uploads unmanaged and potentially causing unnecessary storage consumption."
    },
    {
      "check_id": "CKV_AWS_144",
      "title": "S3 cross-region replication is not enabled",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "CloudTrail logs are stored without cross-region replication, leaving them less resilient to a regional disruption. Replication also requires bucket versioning, which is absent in the original file."
    }
  ],
  "patched_code": "variable "s3_access_log_target_bucket" {
  description = "Name of a dedicated S3 bucket configured to receive server access logs."
  type        = string
}

variable "cloudtrail_replication_destination_bucket_arn" {
  description = "ARN of a versioned S3 replication destination bucket in another AWS region."
  type        = string
}

variable "cloudtrail_replication_role_arn" {
  description = "ARN of an IAM role with permission to replicate objects and delete markers to the destination bucket."
  type        = string
}

resource "aws_s3_bucket" "cloudtrail_logs" {
  bucket = "fleet-management-gps-tracking-system-cloudtrail-${random_string.bucket_suffix.result}"
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_logging" "cloudtrail_logs" {
  bucket        = aws_s3_bucket.cloudtrail_logs.id
  target_bucket = var.s3_access_log_target_bucket
  target_prefix = "cloudtrail-bucket-access/${aws_s3_bucket.cloudtrail_logs.id}/"
}

resource "aws_s3_bucket_lifecycle_configuration" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_replication_configuration" "cloudtrail_logs" {
  depends_on = [aws_s3_bucket_versioning.cloudtrail_logs]

  bucket = aws_s3_bucket.cloudtrail_logs.id
  role   = var.cloudtrail_replication_role_arn

  rule {
    id       = "cross-region-replication"
    priority = 1
    status   = "Enabled"

    filter {}

    destination {
      bucket        = var.cloudtrail_replication_destination_bucket_arn
      storage_class = "STANDARD"
    }

    delete_marker_replication {
      status = "Enabled"
    }
  }
}
",
  "fix_summary": "Added a complete S3 Public Access Block, server access logging, lifecycle cleanup, versioning, and cross-region replication. The logging destination and replication destination and role are supplied through variables so no placeholder credentials or environment-specific identifiers are embedded."
}
